from solution import check_type


def test_issue_example_all_ints():
    """Example: all elements have same data type so result is True."""
    assert check_type((5, 6, 7, 3, 5, 6)) == True  # 6/6 of type int, 6==6 => True


def test_issue_all_strings():
    """All elements have same data type so result is True."""
    assert check_type(("a", "b", "c")) == True  # 3/3 of type str, 3==3 => True


def test_issue_all_floats():
    """All elements have same data type so result is True."""
    assert check_type((1.5, 2.5, 3.0)) == True  # 3/3 of type float, 3==3 => True


def test_issue_mixed_int_and_str():
    """Not all elements have same data type so result is False."""
    assert check_type((5, "6")) == False  # 1 int + 1 str, 1!=2 => False


def test_issue_mixed_int_and_float():
    """Not all elements have same data type so result is False."""
    assert check_type((5, 6, 7.0)) == False  # 2 int + 1 float, 2!=3 => False


def test_issue_bool_vs_int():
    """Bool and int are different data types so result is False."""
    assert check_type((True, 1)) == False  # 1 bool + 1 int, 1!=2 => False


def test_issue_single_element():
    """One element trivially has same data type so result is True."""
    assert check_type((42,)) == True  # 1/1 of type int, 1==1 => True


def test_issue_empty_tuple():
    """Empty tuple vacuously has same data type so result is True."""
    assert check_type(()) == True  # 0 elements, 0==0 => True


def test_issue_last_element_differs():
    """Not all elements have same data type so result is False."""
    assert check_type((1, 1, 1, 1, "1")) == False  # 4 int + 1 str, 4!=5 => False


def test_issue_none_mixed_with_int():
    """Not all elements have same data type so result is False."""
    assert check_type((None, 1)) == False  # 1 NoneType + 1 int, 1!=2 => False


def test_contract_list_elements_same_type():
    """Same data type with different values is still True."""
    assert check_type(([1], [2, 3], [])) == True  # 3/3 of type list, 3==3 => True


def test_contract_exact_bool_return():
    """Function returns True or False as an exact bool."""
    assert check_type((1, 2)) is True  # 2/2 of type int, 2==2 => True
